-- 000464: Seed the STD_WEIGHT parameter definition + per-product values so PPC can
-- generate a lot number at work-order creation.
--
-- WHY: services/ppc resolves three inputs before minting a lot (ppc
-- internal/application/workorder/service.go lotProvisionRequest): the plan item's
-- product, that product's item/shade codes, and the STD_WEIGHT well-known parameter
-- (internal/domain/workorder/value_objects.go WellKnownStdWeight). Live finance_db had
-- NO STD_WEIGHT row in mst_parameter at all, so resolveStdWeight always returned zero
-- and EVERY blank-lot work order was rejected with ErrLotSpecUnavailable. The rejection
-- is deliberate and stays -- PPC never registers a lot against an invented weight -- so
-- the fix is the missing data, not the rule.
--
-- WHERE THE NUMBERS COME FROM (no value here is invented):
-- Every weight below is the MODAL lm_std_weight_full observed in ppc_db.lot_master for
-- that product's ERP item code, over the 66,001 MMSMERGE rows synced from the legacy MMS
-- system. Only products whose item code has >= 10 historical lots carrying a weight are
-- seeded, so each value rests on real production evidence rather than an estimate.
-- Products without that evidence are deliberately LEFT UNSEEDED: they will still be
-- rejected at lot generation, which is the correct outcome.
--
-- NOT DERIVED FROM NET_BOB_WT. mst_parameter already has NET_BOB_WT (Packing, 13,429
-- values), but it is a different quantity: correlation against the lot_master modal over
-- the 1,633 items present in both is only r=0.55 with a 0.96 kg mean absolute difference.
-- Using it would have mis-priced bobbins in exactly the way lot.go warns about.
--
-- STD_WEIGHT is INPUT/Machine so it resolves through the same display-group path the WO
-- parameter materialisation already uses; uom KG matches lm_std_weight_full's unit.
-- Idempotent: the definition upserts on the partial unique index (param_code WHERE
-- deleted_at IS NULL), the values on cpp_unique_product_param.
BEGIN;

-- 1. The STD_WEIGHT definition. idx_mst_parameter_code is a PARTIAL unique index
--    (WHERE deleted_at IS NULL), so the conflict target must repeat that predicate.
--
-- 1a. RESURRECT FIRST. The down migration soft-deletes this definition (it cannot hard
--     delete it: cost_product_parameter has an FK onto it, and down deliberately keeps
--     any hand-edited value). Without this step a down/up cycle would insert a SECOND
--     definition with a fresh id, orphaning those kept values against the old row and
--     leaving two STD_WEIGHT rows in the table. Un-deleting the row we previously
--     created keeps ids stable across the cycle and reattaches the kept values.
UPDATE mst_parameter
   SET deleted_at = NULL, deleted_by = NULL, is_active = TRUE,
       updated_at = now(), updated_by = 'seed_ppc_lot'
 WHERE param_code = 'STD_WEIGHT'
   AND created_by = 'seed_ppc_lot'
   AND deleted_at IS NOT NULL
   -- Guard the partial unique index: only resurrect if no live row already holds
   -- the code, otherwise this UPDATE would collide with it.
   AND NOT EXISTS (
     SELECT 1 FROM mst_parameter live
      WHERE live.param_code = 'STD_WEIGHT' AND live.deleted_at IS NULL
   );

  param_code, param_name, param_short_name, data_type, param_category,
  uom_id, display_group, display_order, is_active, is_required_for_costing,
  notes, created_by
)
SELECT
  'STD_WEIGHT', 'Standard Bobbin Weight', 'Std Bobbin Wt', 'NUMBER', 'INPUT',
  (SELECT uom_id FROM mst_uom WHERE uom_code = 'KG'),
  'Machine', 20, TRUE, FALSE,
  'Standard full-bobbin weight. Consumed by PPC lot generation and the daily-performance efficiency engine as a well-known parameter.',
  'seed_ppc_lot'
ON CONFLICT (param_code) WHERE deleted_at IS NULL DO NOTHING;

-- 2. Per-product values, keyed by cpm_product_sys_id. Staged first so the product FK and
--    the parameter id are resolved in one place.
DROP TABLE IF EXISTS _stg_std_weight;
CREATE TEMP TABLE _stg_std_weight (product_sys_id BIGINT, std_weight NUMERIC(20,6)) ON COMMIT DROP;


  cpp_product_sys_id, cpp_param_id, cpp_value_numeric, cpp_filled_by, cpp_created_by
)
SELECT s.product_sys_id, p.id, s.std_weight, 'seed_ppc_lot', 'seed_ppc_lot'
FROM _stg_std_weight s
CROSS JOIN (SELECT id FROM mst_parameter WHERE param_code = 'STD_WEIGHT' AND deleted_at IS NULL) p
-- Defensive: a product row could have been deleted between generating this seed and
-- running it; the FK would abort the whole migration.
WHERE EXISTS (SELECT 1 FROM cost_product_master m WHERE m.cpm_product_sys_id = s.product_sys_id)
ON CONFLICT (cpp_product_sys_id, cpp_param_id) DO NOTHING;

DO $$
DECLARE n INTEGER; defs INTEGER;
BEGIN
  SELECT count(*) INTO defs FROM mst_parameter WHERE param_code = 'STD_WEIGHT' AND deleted_at IS NULL;
  SELECT count(*) INTO n FROM cost_product_parameter v
    JOIN mst_parameter p ON p.id = v.cpp_param_id
   WHERE p.param_code = 'STD_WEIGHT';
  RAISE NOTICE '000464: STD_WEIGHT definitions=% values=% (expected 1 and up to 4198)', defs, n;
  IF defs <> 1 THEN
    RAISE EXCEPTION '000464: expected exactly one STD_WEIGHT definition, found %', defs;
  END IF;
END $$;

COMMIT;
